import java.util.Arrays;

public class Des3DkCrypto extends DkCrypto {

    private static final byte[] ZERO_IV = new byte[] {0, 0, 0, 0, 0, 0, 0, 0};

    public Des3DkCrypto() {
    }

    protected int getKeySeedLength() {
        return 168;   // bits; 3DES key material has 21 bytes
    }

    public byte[] stringToKey(char[] salt) throws GeneralSecurityException {
        byte[] saltUtf8 = null;
        try {
            saltUtf8 = charToUtf8(salt);
            return stringToKey(saltUtf8, null);
        } finally {
            if (saltUtf8 != null) {
                Arrays.fill(saltUtf8, (byte)0);
            }
            // Caller responsible for clearing its own salt
        }
    }

    private byte[] stringToKey(byte[] secretAndSalt, byte[] opaque)
        throws GeneralSecurityException {

        if (opaque != null && opaque.length > 0) {
            throw new RuntimeException("Invalid parameter to stringToKey");
        }

        byte[] tmpKey = randomToKey(nfold(secretAndSalt, getKeySeedLength()));
        return dk(tmpKey, KERBEROS_CONSTANT);
    }

    public byte[] parityFix(byte[] value)
        throws GeneralSecurityException {
        // fix key parity
        setParityBit(value);
        return value;
    }

    /*
     * From RFC 3961.
     *
     * The 168 bits of random key data are converted to a protocol key value
     * as follows.  First, the 168 bits are divided into three groups of 56
     * bits, which are expanded individually into 64 bits as in des3Expand().
     * Result is a 24 byte (192-bit) key.
     */
    protected byte[] randomToKey(byte[] in) {
        if (in.length != 21) {
            throw new IllegalArgumentException("input must be 168 bits");
        }

        byte[] one = keyCorrection(des3Expand(in, 0, 7));
        byte[] two = keyCorrection(des3Expand(in, 7, 14));
        byte[] three = keyCorrection(des3Expand(in, 14, 21));

        byte[] key = new byte[24];
        System.arraycopy(one, 0, key, 0, 8);
        System.arraycopy(two, 0, key, 8, 8);
        System.arraycopy(three, 0, key, 16, 8);

        return key;
    }

    private static byte[] keyCorrection(byte[] key) {
        // check for weak key
        try {
            if (DESKeySpec.isWeak(key, 0)) {
                key[7] = (byte)(key[7] ^ 0xF0);
            }
        } catch (InvalidKeyException ex) {
            // swallow, since it should never happen
        }
        return key;
    }

    /**
     * From RFC 3961.
     *
     * Expands a 7-byte array into an 8-byte array that contains parity bits.
     * The 56 bits are expanded into 64 bits as follows:
     *   1  2  3  4  5  6  7  p
     *   9 10 11 12 13 14 15  p
     *   17 18 19 20 21 22 23  p
     *   25 26 27 28 29 30 31  p
     *   33 34 35 36 37 38 39  p
     *   41 42 43 44 45 46 47  p
     *   49 50 51 52 53 54 55  p
     *   56 48 40 32 24 16  8  p
     *
     * (PI,P2,...,P8) are reserved for parity bits computed on the preceding
     * seven independent bits and set so that the parity of the octet is odd,
     * i.e., there is an odd number of "1" bits in the octet.
     *
     * @param start index of starting byte (inclusive)
     * @param end index of ending byte (exclusive)
     */
    private static byte[] des3Expand(byte[] input, int start, int end) {
        if ((end - start) != 7)
            throw new IllegalArgumentException(
                "Invalid length of DES Key Value:" + start + "," + end);

        byte[] result = new byte[8];
        byte last = 0;
        System.arraycopy(input, start, result, 0, 7);
        byte posn = 0;

        // Fill in last row
        for (int i = start; i < end; i++) {
            byte bit = (byte) (input[i]&0x01);
            if (debug) {
                System.out.println(i + ": " + Integer.toHexString(input[i]) +
                    " bit= " + Integer.toHexString(bit));
            }
            ++posn;
            if (bit != 0) {
                last |= (bit<<posn);
            }
        }

        if (debug) {
            System.out.println("last: " + Integer.toHexString(last));
        }
        result[7] = last;
        setParityBit(result);
        return result;
    }

    /**
     * Sets the parity bit (0th bit) in each byte so that each byte
     * contains an odd number of 1's.
     */
    private static void setParityBit(byte[] key) {
        for (int i = 0; i < key.length; i++) {
            int b = key[i] & 0xfe;
            b |= (Integer.bitCount(b) & 1) ^ 1;
            key[i] = (byte) b;
        }
    }

    protected Cipher getCipher(byte[] key, byte[] ivec, int mode)
        throws GeneralSecurityException {
        // NoSuchAlgorithException
        SecretKeyFactory factory = SecretKeyFactory.getInstance("desede");

        // InvalidKeyException
        KeySpec spec = new DESedeKeySpec(key, 0);

        // InvalidKeySpecException
        SecretKey secretKey = factory.generateSecret(spec);

        // IV
        if (ivec == null) {
            ivec = ZERO_IV;
        }

        // NoSuchAlgorithmException, NoSuchPaddingException
        // NoSuchProviderException
        Cipher cipher = Cipher.getInstance("DESede/CBC/NoPadding");
        IvParameterSpec encIv = new IvParameterSpec(ivec, 0, ivec.length);

        // InvalidKeyException, InvalidAlgorithParameterException
        cipher.init(mode, secretKey, encIv);

        return cipher;
    }

    public int getChecksumLength() {
        return 20;  // bytes
    }

    protected byte[] getHmac(byte[] key, byte[] msg)
        throws GeneralSecurityException {

        SecretKey keyKi = new SecretKeySpec(key, "HmacSHA1");
        Mac m = Mac.getInstance("HmacSHA1");
        m.init(keyKi);
        return m.doFinal(msg);
    }
}

Qiu S, Liu B, Mo Y, et al. MicroRNA‐153‐3p increases autophagy in sevoflurane‐preconditioned mice to protect against ischaemic/reperfusion injury after knee arthroplasty. J Cell Mol Med. 2020;24:5330--5340. 10.1111/jcmm.15188

1. INTRODUCTION {#jcmm15188-sec-0001}
===============

The use of a tourniquet is employed in total knee arthroplasty (TKA) procedures in order to prevent blood loss.[^1^](#jcmm15188-bib-0001){ref-type="ref"} Furthermore, in the event a tourniquet is inflated, ischaemia will be induced to an extremity, the release of which results in subsequent ischaemia/reperfusion injury (IRI) to localized skeletal muscle, to systemic circulation and in some instances to vital distant organs such as the heart, kidneys, lungs and brain.[^2^](#jcmm15188-bib-0002){ref-type="ref"} IRI of limbs and distal organs induced by tourniquet has been reported by various studies following TKA.[^3^](#jcmm15188-bib-0003){ref-type="ref"} Similarly, accumulating studies continue to highlight IRI as an issue requiring further investigations in knee arthroplasty.[^4^](#jcmm15188-bib-0004){ref-type="ref"}, [^5^](#jcmm15188-bib-0005){ref-type="ref"}, [^6^](#jcmm15188-bib-0006){ref-type="ref"}, [^7^](#jcmm15188-bib-0007){ref-type="ref"} A previous study concluded that myocardial IRI could be repressed by means of sevoflurane‐increased autophagy.[^8^](#jcmm15188-bib-0008){ref-type="ref"} Sevoflurane has also been reported to attenuate IRI in certain organs including the heart, lung and liver in mice administered with sevoflurane, illustrated by a superior recovery following IRI.[^9^](#jcmm15188-bib-0009){ref-type="ref"}, [^10^](#jcmm15188-bib-0010){ref-type="ref"}, [^11^](#jcmm15188-bib-0011){ref-type="ref"}, [^12^](#jcmm15188-bib-0012){ref-type="ref"}, [^13^](#jcmm15188-bib-0013){ref-type="ref"} Additionally, a recent study demonstrated that the use of hyperbaric oxygen preconditioning confers neuro‐protective effects against IRI in neurocyte a process of which involves the induction of autophagy, highlighting the possible link between autophagy and protection against IRI following TKA.[^14^](#jcmm15188-bib-0014){ref-type="ref"}

The ability of microRNAs (miRs) to regulate gene expression at a post‐transcriptional level has been shown to influence ischaemic preconditioning, ischaemic post‐conditioning and IRI.[^15^](#jcmm15188-bib-0015){ref-type="ref"} Additionally, miR‐153‐3p has been implicated in acute graft‐versus‐host disease.[^16^](#jcmm15188-bib-0016){ref-type="ref"} Furthermore, studies have indicated that B‐cell lymphoma‐2 gene (Bcl‐2) is directly targeted by miR‐153‐3p.[^17^](#jcmm15188-bib-0017){ref-type="ref"} As a suppressor of apoptosis, Bcl‐2 has been widely documented to promote cell survival and inhibits cell death.[^18^](#jcmm15188-bib-0018){ref-type="ref"} Furthermore, it has been observed that in human SGC‐7901 cells, Beclin1‐dependent autophagy is stimulated by small interfering RNA‐mediated Bcl‐2 silencing.[^19^](#jcmm15188-bib-0019){ref-type="ref"} Existing literature has revealed that the disrupted interaction between Beclin1 and Bcl‐2 arises following activation of AMPK which enhances autophagy and decreases cardiomyocyte apoptosis, which has been shown to be beneficial for the treatment of diabetic cardiomyopathy.[^20^](#jcmm15188-bib-0020){ref-type="ref"} Similarly, another study explored the contribution of the interaction between Beclin1 and Bcl‐2 induced by mammalian Ste20‐like kinase 1 (Mst1) and the suppression of autophagy.[^21^](#jcmm15188-bib-0021){ref-type="ref"} Notably, Peng et al provided evidence indicating that myocardial tissue is protected against IRI following ischaemic preconditioning (IPC) which blocks the interaction of Beclin1 and Bcl‐2 to increase autophagy.[^22^](#jcmm15188-bib-0022){ref-type="ref"} Based on the aforementioned studies, we hypothesized that miR‐153‐3p promotes the protection and alleviates the effects of IRI by mediating autophagy through the interaction between Beclin1 a

[…]

ponding mutant fragment was inserted into the luciferase reporter vector (Beijing Huayueyang Biotechnology Co., Ltd.) in order to obtain the Bcl‐2‐wild‐type (WT) and Bcl‐2‐mutant‐type (MUT) reporter plasmids, respectively. The reporter plasmids were cotransfected with miR‐153‐3p mimic or the control plasmid into cells. Ranilla luciferase was employed as the internal reference. After 48 hours, the cells were collected and lysed. Luciferase reporter gene assay was performed on the dual‐luciferase reporter gene analysis system (Promega) based on the instructions of the luciferase assay kit (K801‐200, BioVision Research Products). The relative luciferase activity of the target reporter gene was calculated based on the ratio of the relative light units (RLU) of firefly luciferase to the RLU of the renilla luciferase.

2.15. Statistical analysis {#jcmm15188-sec-0017}
--------------------------

Statistical analyses were conducted using SPSS 21.0 (IBM). Measurement data were expressed as mean ± standard deviation. If the data conformed to normal distribution and homogeneity of variances, the comparison between two groups in non‐paired design was analysed via non‐paired *t* test, and comparisons among multiple groups were performed by one‐way analysis of variance (ANOVA), followed by Turkey\'s post hoc test. *P* \< .05 was considered to be indicative of statistical significance.

3. RESULTS {#jcmm15188-sec-0018}
==========

3.1. miR‐153‐3p is up‐regulated in IRI chondrocytes and mice pre‐treated with sevoflurane {#jcmm15188-sec-0019}
-----------------------------------------------------------------------------------------

The mouse primary chondrocytes were initially isolated and cultured, after which the matrix secreted by the chondrocyte was stained with Alcian blue in order to confirm the chondrocyte characteristics. RT‐qPCR was conducted to determine collagen ΙΙ expression in the chondrocytes. As depicted in Figure [1A‐B](#jcmm15188-fig-0001){ref-type="fig"}, after 7 days of incubation, the secretion of extracellular matrix as well as the expression of collagen ΙΙ was increased (*P* \< .05), which was indicative of successful isolation of the chondrocytes. The primary chondrocytes from naive mice were cultured with either a medium containing 10% FBS, 0% FBS or sevoflurane. Diminished expression of miR‐153‐3p was detected in 0% FBS‐treated chondrocytes when compared to 10% FBS‐treated chondrocytes (*P* \< .05). Sevoflurane treatment led to an elevated miR‐153‐3p expression in the presence of 0% FBS (Figure [1C](#jcmm15188-fig-0001){ref-type="fig"}).

![Sevoflurane preconditioning increases miR‐153‐3p expression in IRI chondrocytes and mice. A, Identification of isolated mouse primary chondrocytes by Alcian blue staining (200 ×). B, Expression of collagen ΙΙ in chondrocytes incubated at day 0 and day 7 determined by RT‐qPCR. C, Expression of miR‐153‐3p in chondrocytes treated with 10% FBS, 0% FBS and 0% FBS+ sevoflurane measured by RT‐qPCR. D, Pathological damage degree of sham‐operated mice, IRI mice and IRI mice treated with sevoflurane detected by HE staining (200 ×). E, Expression of miR‐153‐3p in sham‐operated mice, IRI mice and IRI mice treated with sevoflurane measured by RT‐qPCR. N = 6. \**P* \< .05 vs chondrocytes incubated for 0 d, chondrocytes treated with 0% FBS, or IRI mice. ^\#^ *P \< *.05 vs IRI chondrocytes. Measurement data were expressed as mean ± standard deviation. The comparison between two groups was analysed by the non‐paired *t* test, and comparisons among multiple groups were performed by one‐way ANOVA, followed by Turkey\'s post hoc test. The cell experiment was repeated 3 times](JCMM-24-5330-g001){#jcmm15188-fig-0001}

After the IRI mouse model post‐TKA had been established, the IRI mice were either treated or not treated with sevoflurane through inhalation during modelling. Following completion of the operative procedures, swelling of the entire knee joint as well as a high skin temperature was iden

[…]

phagy induced by hyperbaric oxygen preconditioning, a finding of which was consistent with the results of the current study.[^14^](#jcmm15188-bib-0014){ref-type="ref"} Similarly, existing literature has demonstrated that remote limb ischaemic post‐conditioning confers cardio protection against myocardial IRI in normal mice by inducing autophagy.[^37^](#jcmm15188-bib-0037){ref-type="ref"}

Furthermore, a key finding of the current study illustrated that miR‐153‐3p overexpression promotes autophagy by means of disrupting the interaction between Bcl‐2 and Beclin1 in IRI mice following TKA. It is well acknowledged that Beclin1 is involved at various stages of myocardial IRI.[^38^](#jcmm15188-bib-0038){ref-type="ref"} Tang et al concluded that HBV × protein increases autophagy by increasing Beclin1 expression.[^39^](#jcmm15188-bib-0039){ref-type="ref"} Moreover, a previous study revealed promoted autophagy in N2a with IRI after melatonin treatment, accompanied by an elevation in the expressions of Beclin1 and LC3‐II expression.[^40^](#jcmm15188-bib-0040){ref-type="ref"} Bcl‐2 has been proven to interact with Beclin1 and contribute to the suppression of Beclin1‐dependent autophagy.[^41^](#jcmm15188-bib-0041){ref-type="ref"} Du et al revealed that Bcl‐2 silencing promotes Beclin1‐dependent autophagy in gastric cancer cells.[^19^](#jcmm15188-bib-0019){ref-type="ref"} Disruption of the interaction between Bcl‐2 and Beclin1 has been implicated in maslinic acid‐promoted autophagy in rat pheochromocytoma cells.[^42^](#jcmm15188-bib-0042){ref-type="ref"} Another study indicated that autophagy is induced by blocking the interaction between Bcl‐2 and Beclin1, as a result of BH3 mimetic S1 promoting autophagy via blockade of Bcl‐2/Beclin1 interaction in human glioma cells.[^43^](#jcmm15188-bib-0043){ref-type="ref"} More importantly, a previous investigation demonstrated that Bcl‐2 was directly targeted and negatively regulated by miR‐153‐3p.[^17^](#jcmm15188-bib-0017){ref-type="ref"}

In conclusion, the findings of our study present in vivo and in vitro evidence supporting the notion that miR‐153‐3p alleviates IRI in sevoflurane pre‐treated chondrocytes and mice following TKA, via the induction of autophagy by blocking the interaction between Bcl‐2 and Beclin1 (Figure [6](#jcmm15188-fig-0006){ref-type="fig"}). Our findings highlight the potential of miR‐153‐3p up‐regulation as a potential clinically viable target capable of enhancing the protection of sevoflurane preconditioning against IRI following TKA. The potential role of sevoflurane in regulation of Beclin1 was not fully explored. Therefore, more detailed experiments are needed in the future to confirm the findings of our study.

